from rdkit import Chem

smiles = "CCOC(=O)c1c(OC)cc(-c2cnc(OC)c(OC)c2)nc1CBr"
mol = Chem.MolFromSmiles(smiles)

if mol:
    print("Molecule parsed successfully")
    print(f"Number of atoms: {mol.GetNumAtoms()}")

    # Get the pyridine ring
    for bond in mol.GetBonds():
        if bond.IsInRing():
            pass

    # Find the bromomethyl group
    for atom in mol.GetAtoms():
        if atom.GetAtomicNum() == 35:  # Br
            print(f"Bromine attached to atom {atom.GetIdx()}")
            for neighbor in atom.GetNeighbors():
                print(f"  Neighbor: atom {neighbor.GetIdx()}, element {neighbor.GetSymbol()}, degree {neighbor.GetDegree()}")
                if neighbor.GetDegree() == 1:
                    print(f"    This is a CH2Br group!")

    # Find ester
    for atom in mol.GetAtoms():
        if atom.GetAtomicNum() == 6 and atom.GetTotalNumOfHs() == 0:
            for bond in atom.GetBonds():
                if bond.GetBondType() == Chem.BondType.DOUBLE:
                    neighbor = bond.GetOtherAtom(atom)
                    if neighbor.GetAtomicNum() == 8:  # Oxygen
                        print(f"Ester carbonyl at atom {atom.GetIdx()}")

    # Print connectivity around key positions
    print("\nKey structural features:")
    for atom in mol.GetAtoms():
        if atom.GetAtomicNum() == 7:  # Nitrogen in ring
            print(f"Ring nitrogen at position {atom.GetIdx()}")
            for neighbor in atom.GetNeighbors():
                print(f"  Connected to: atom {neighbor.GetIdx()}, element {neighbor.GetSymbol()}")
else:
    print("Failed to parse SMILES")
EOF
